const-string v3, "<html>
    <head>
        <meta charset="utf-8">
        <meta name="viewport" content="width=device-width, initial-scale=1.0">
        <title>网络异常</title>
    </head>
    <body>
        <h1>网络连接失败</h1>
        <p>请检查网络设置；网络恢复后会自动重连</p>
        <h2><span onclick="refresh()">点此重试</span></h2>
        <h3><input id="url" type="text" placeholder="备用:手动输入地址"> <button onclick="go()">打开</button></h3>
        <style>
            body {text-align: center;margin-top: 28%;font-family: sans-serif;background:#111;color:#ddd;}
            h1 {color: #e05252;font-size:1.6em;}
            p  {color:#888;font-size:.95em;}
            h2 {color: cornflowerblue;cursor:pointer;}
            input,button {font-size:1em;padding:4px 8px;}
        </style>
        <script>
            function refresh() {
                var el = document.getElementsByTagName("h2")[0];
                el.innerText = "正在重试…";
                if (window.Android) { window.Android.resolveDns(); }
                /* 重试再失败会整页重载错误页复位文字；这里兜底 12s 后恢复按钮,避免卡死在"正在重试" */
                setTimeout(function () { el.innerText = "点此重试"; }, 12000);
            }
            function go() {
                var url = document.getElementById("url").value;
                if (!url) return;
                if(url.indexOf("http") < 0) url = "https://" + url;
                window.location.href = url;
            }
        </script>
    </body>
</html>"

